    // CookCredit landing
    hero_tagline:"Dale crédito a quien cocina.",
    hero_subtitle:"Cocinen juntos. Propina al chef. Giren la ruleta.",
    how_title:"Cómo funciona",
    step4_title:"Gira la ruleta",
    step4_desc:"¿No saben quién cocina? Gírenla. ¿No saben quién da propina? Gírenla de nuevo. El más desafortunado se lleva un trofeo.",
    inside_title:"Qué hay dentro de una casa",
    feat_board:"El Tablero", feat_board_desc:"Publica notas, comparte lo que hay en la nevera, planifica la cena juntos. Como una puerta de nevera digital.",
