    install_ios_title:"Tres toques rápidos en Safari",
 install_ios_step1:"Toca el botón <strong> compartir</strong> en la parte inferior de Safari",
    install_ios_step2:"Desplázate y toca <strong>\"Agregar a inicio\"</strong>",
