    beam_ai_hint:"ፍላጎትዎን በማንኛውም ቋንቋ ይግለጹ — ጥሪውን አዘጋጅልዎታለሁ።",
    beam_ai_ph:"ለምሳሌ ለአራት ሰው ቅመም ያለው ምግብ ዛሬ ማታ",
    beam_ai_send:"ላክ",
    beam_ai_filled:"ጥሪዎ ከታች ተዘጋጅቷል — ገምግመው ይላኩት።",
    beam_ai_unavailable:"ረዳቱ አሁን አይገኝም።",
    beam_mine_error:"ጥሪዎችዎን መጫን አልተቻለም — ግንኙነትዎን ያረጋግጡ።",
    beam_action_error:"አልተሳካም — ግንኙነትዎን አረጋግጠው እንደገና ይሞክሩ።",
    load_retry:"እንደገና ሞክር",
    offline_banner:"ከመስመር ውጭ ነዎት — እስኪመለሱ ድረስ አንዳንድ ተግባራት አይሰሩም።",
    beam_nav:"ጥሪ", beam_requests_nav:"ጥሪዎች",
    beam_title:"ምግብ ጥራ", beam_what:"ምን ትፈልጋለህ?",
    beam_photo:"ፎቶ ጨምር (አማራጭ)", beam_scope_nearby:"በአቅራቢያ", beam_scope_citywide:"በከተማ ዙሪያ",
    beam_city:"ከተማ", beam_send:"ላክ", beam_sending:"በመላክ ላይ...",
