    lp_t1_q:"የተረጋገጠ ነጥቧን አነበብኩ፣ የቢላ ፈተናውን ተመለከትኩ እና ቀጠርኩ። አስደናቂ እራት አበሰለች እና ኩሽናዬን ጥርት አድርጋ ተወችው።",
    lp_t2_q:"የቢላ ችሎታዬን በካሜራ ማረጋገጥ ማለት የማላውቀው ሰው ባገኘኝ ቅጽበት ያምነኛል — እንዲሁም የሚቀጥሩ ኩሽናዎች።",
    lp_t3_q:"ከሬዙሜ መገመትን አቆምን። የተረጋገጠውን የመክተፍ ነጥብ አይተን በችሎታ ለአጭር ዝርዝር እንመርጣለን።",
